sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var P = 'x_2056099_indust_0_';
    var passed = 0;
    var total = 0;
    total++;
    var grCust = new GlideRecord(P + 'cust_master');
    grCust.addActiveQuery();
    grCust.setLimit(1);
    grCust.query();
    if (!grCust.next()) { stepResult.setOutputMessage('FAIL: No active customer found'); return false; }
    var custSysId = grCust.getUniqueValue();
    var custName = grCust.getValue('customer_name');
    var custEmail = grCust.getValue('primary_contact_email');
    passed++;
    total++;
    var grLookup = new GlideRecord(P + 'cust_master');
    grLookup.addQuery('primary_contact_email', custEmail);
    grLookup.addActiveQuery();
    grLookup.setLimit(1);
    grLookup.query();
    assertEqual({ name: 'Email lookup finds customer', shouldbe: true, value: grLookup.next() });
    assertEqual({ name: 'Correct sys_id returned', shouldbe: custSysId, value: grLookup.getUniqueValue() });
    assertEqual({ name: 'Correct customer_name returned', shouldbe: custName, value: grLookup.getValue('customer_name') });
    passed++;
    total++;
    var grFake = new GlideRecord(P + 'cust_master');
    grFake.addQuery('primary_contact_email', 'atf_nonexistent_9999@test.invalid');
    grFake.addActiveQuery();
    grFake.setLimit(1);
    grFake.query();
    assertEqual({ name: 'Unlinked email returns no customer', shouldbe: false, value: grFake.hasNext() });
    passed++;
    total++;
    var grAll = new GlideRecord(P + 'cust_master');
    grAll.addActiveQuery();
    grAll.query();
    var allCount = 0;
    while (grAll.next()) allCount++;
    if (allCount > 1) {
        var grFirst = new GlideRecord(P + 'cust_master');
        grFirst.addActiveQuery();
        grFirst.orderBy('sys_created_on');
        grFirst.setLimit(1);
        grFirst.query();
        grFirst.next();
        var firstId = grFirst.getUniqueValue();
        var grSecond = new GlideRecord(P + 'cust_master');
        grSecond.addActiveQuery();
        grSecond.orderBy('sys_created_on');
        grSecond.setLimit(2);
        grSecond.query();
        grSecond.next(); grSecond.next();
        var secondEmail = grSecond.getValue('primary_contact_email');
        var grCheck = new GlideRecord(P + 'cust_master');
        grCheck.addQuery('primary_contact_email', secondEmail);
        grCheck.addActiveQuery();
        grCheck.setLimit(1);
        grCheck.query();
        grCheck.next();
        assertEqual({ name: 'No first-active-customer fallback', shouldbe: true, value: grCheck.getUniqueValue() !== firstId || secondEmail === grFirst.getValue('primary_contact_email') });
    }
    passed++;
    total++;
    if (allCount > 1) {
        var grA = new GlideRecord(P + 'cust_master');
        grA.addActiveQuery();
        grA.setLimit(1);
        grA.query();
        grA.next();
        var emailA = grA.getValue('primary_contact_email');
        var nameA = grA.getValue('customer_name');
        var grLookA = new GlideRecord(P + 'cust_master');
        grLookA.addQuery('primary_contact_email', emailA);
        grLookA.addActiveQuery();
        grLookA.setLimit(1);
        grLookA.query();
        grLookA.next();
        assertEqual({ name: 'Customer data not mixed', shouldbe: nameA, value: grLookA.getValue('customer_name') });
    }
    passed++;
    stepResult.setOutputMessage('Identity: ' + passed + '/' + total + ' passed');
    return true;
})(outputs, steps, params, stepResult, assertEqual);
